  reg [2:0] state, next_state;
  wire [2:0] wd1, wd2, wd3;
  reg [1:0] cnt;
  wire [1:0] cnt2;
  reg zreg;
  always @(*) begin
    case (state)
      3'b000: next_state = s ? 3'b001 : 3'b000;
      3'b001: next_state = {s, wd1};
      3'b010: next_state = {s, wd2};
      3'b011: next_state = {s, wd3};
      3'b100: next_state = {s, w};
      default: next_state = 3'b000;
    endcase
  end
