// One-hot state encoding: state A is 3-hot (s=0, w=0), state B is 3-hot
// (s=0, w=1), state C is 3-hot (s=1, w=0), state D is 3-hot (s=1, w=1).
// The combinational next_state function computes the one-hot encoding of the
// next state, given the current state and the inputs s and w.
module TopModule(input  clk, input  reset, input  s, input  w, output z);
  reg [2:0] state, next_state;
  wire s_0 = (state[0] && !state[1] && !state[2]);
  wire s_1 = (state[1] && !state[0] && !state[2]);
  wire w_0 = (s_0 && !w) || (s_1 && w);
  wire w_1 = (s_0 && w) || (s_1 && !w);
  always @(*) begin
    case ({s, w})
      2'b00: next_state = 3'b100;
      2'b01: next_state = 3'b010;
      2'b10: next_state = 3'b001;
      2'b11: next_state = 3'b000;
    endcase
  end
  always @(posedge clk) begin
    if (reset) state <= 3'b100;
    else state <= next_state;
  end
  assign z = s_1 & w_0 & w_1;
endmodule

